1	/* MIST Console front-end. Multi-session (left tab rail), each tab a headless
2	   claude streamed over SSE. We render the whole UI ourselves. */
3	"use strict";
4	
5	const $ = (s) => document.querySelector(s);
6	const logs = $("#logs");
7	const tabsEl = $("#tabs");
8	const input = $("#input");
9	const statusEl = $("#status");
10	
11	/* ---------- safe markdown ---------- */
12	function esc(s) {
13	  return s.replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
14	}
15	function md(src) {
16	  const fences = [];
17	  src = src.replace(/```(\w*)\n([\s\S]*?)```/g, (_, lang, code) => {
18	    fences.push(
19	      '<div class="codeblock"><button class="copy-btn" type="button" aria-label="Copy code">Copy</button>' +
20	      `<pre><code>${esc(code)}</code></pre></div>`
21	    );
22	    return ` �${fences.length - 1}� `;
23	  });
24	  src = esc(src);
25	  src = src
26	    .replace(/`([^`]+)`/g, "<code>$1</code>")
27	    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
28	    .replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>")
29	    .replace(/^### (.*)$/gm, "<h3>$1</h3>")
30	    .replace(/^## (.*)$/gm, "<h2>$1</h2>")
31	    .replace(/^# (.*)$/gm, "<h1>$1</h1>")
32	    .replace(/^\s*[-*] (.*)$/gm, "<li>$1</li>")
33	    .replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '<a href="$2">$1</a>');
34	  // autolink bare URLs (those not already inside an href="" or anchor text)
35	  src = src.replace(
36	    /(^|[\s(])(https?:\/\/[^\s<>()]+[^\s<>().,;:!?'"])/g,
37	    '$1<a href="$2">$2</a>'
38	  );
39	  src = src.replace(/(<li>[\s\S]*?<\/li>)/g, "<ul>$1</ul>").replace(/<\/ul>\s*<ul>/g, "");
40	  src = src
41	    .split(/\n{2,}/)
42	    .map((p) => (/^\s*<(h\d|ul|pre|blockquote)/.test(p) ? p : `<p>${p.replace(/\n/g, "<br>")}</p>`))
43	    .join("");
44	  src = src.replace(/�(\d+)�/g, (_, i) => fences[+i]);
45	  return src;
46	}
47	
48	function toolSummary(name, input) {
49	  if (!input || typeof input !== "object") return "";
50	  if (input.file_path) return input.file_path.split("/").pop();
51	  if (input.command) return String(input.command).split("\n")[0].slice(0, 70);
52	  if (input.path) return String(input.path).split("/").pop();
53	  if (input.pattern) return String(input.pattern);
54	  if (input.query) return String(input.query).slice(0, 60);
55	  if (input.url) return String(input.url);
56	  try { const s = JSON.stringify(input); return s.length > 70 ? s.slice(0, 70) + "…" : s; }
57	  catch (_) { return ""; }
58	}
59	
60	function el(tag, cls, html) {
61	  const e = document.createElement(tag);
62	  if (cls) e.className = cls;
63	  if (html != null) e.innerHTML = html;
64	  return e;
65	}
66	
67	/* ---------- session registry ---------- */
68	const sessions = new Map();
69	let activeId = null;
70	let SPINNER_VERBS = ["Thinking it through, properly"];
71	let MODELS = [];
72	let spinnerIdx = 0;
73	let lastInit = null;
74	try { lastInit = JSON.parse(localStorage.getItem("lastInit") || "null"); } catch (_) {}
75	
76	class Session {
77	  constructor(id, title, info) {
78	    info = info || {};
79	    this.id = id;
80	    this.title = title || "New chat";
81	    this.pinned = !!info.pinned;
82	    this.model = info.model || "";
83	    this.lastActivity = info.last_activity ? info.last_activity * 1000 : Date.now();
84	    this.logEl = el("div", "session-log");
85	    this.logEl.hidden = true;
86	    logs.appendChild(this.logEl);
87	    this.current = null;
88	    this.blocks = {};
89	    this.toolInputs = {};
90	    this.init = null;
91	    this.ctxPct = null;
92	    this.statusState = "idle";
93	    this.statusLabel = "idle";
94	    this.lastUsage = "";
95	    this.spinnerEl = null;
96	    this.es = null;
97	    this.connect();
98	  }
99	
100	  connect() {
101	    if (this.es) this.es.close();
102	    this.es = new EventSource("/stream/" + this.id);
103	    this.es.onmessage = (m) => { try { this.onEvent(JSON.parse(m.data)); } catch (_) {} };
104	    this.es.onerror = () => this.setStatus("error", "disconnected");
105	  }
106	
107	  get active() { return this.id === activeId; }
108	
109	  /* ---- dom helpers (scoped to this tab) ---- */
110	  atBottom() { return this.logEl.scrollHeight - this.logEl.scrollTop - this.logEl.clientHeight < 60; }
111	  scroll() { if (this.active) this.logEl.scrollTop = this.logEl.scrollHeight; }
112	  addMsg(role, who) {
113	    const wrap = el("div", "msg " + role);
114	    wrap.appendChild(el("div", "who", who));
115	    const body = el("div", "body");
116	    wrap.appendChild(body);
117	    this.logEl.appendChild(wrap);
118	    if (this.spinnerEl) this.logEl.appendChild(this.spinnerEl);  // keep spinner last
119	    this.scroll();
120	    return body;
121	  }
122	  showSpinner() {
123	    if (!this.spinnerEl) {
124	      this.spinnerEl = el("div", "spinner", '<span class="sv-glyph">✦</span> <span class="sv"></span>');
125	    }
126	    this.spinnerEl.querySelector(".sv").textContent =
127	      (SPINNER_VERBS[spinnerIdx % SPINNER_VERBS.length] || "Thinking") + "…";
128	    this.logEl.appendChild(this.spinnerEl);   // move to bottom
129	    this.scroll();
130	  }
131	  hideSpinner() {
132	    if (this.spinnerEl) { this.spinnerEl.remove(); this.spinnerEl = null; }
133	  }
134	  notice(text, isErr) {
135	    this.logEl.appendChild(el("div", "notice" + (isErr ? " err" : ""), esc(text)));
136	    this.scroll();
137	  }
138	  setStatus(state, label) {
139	    const busy = state === "thinking" || state === "working";
140	    if (busy && this.statusState !== state && SPINNER_VERBS.length) {
141	      spinnerIdx = Math.floor(Math.random() * SPINNER_VERBS.length);  // fresh verb per turn
142	    }
143	    this.statusState = state;
144	    this.statusLabel = label || state;
145	    if (busy) this.showSpinner(); else this.hideSpinner();
146	    if (this.active) applyStatus(this);
147	  }
148	
149	  /* ---- assistant turn ---- */
150	  beginAssistant() {
151	    this.current = { body: this.addMsg("mist", "MIST"), text: "", textEl: null };
152	    this.blocks = {};
153	    this.toolInputs = {};
154	  }
155	  ensureTextEl() {
156	    if (!this.current.textEl) {
157	      this.current.textEl = el("div", "md");
158	      this.current.body.appendChild(this.current.textEl);
159	    }
160	    return this.current.textEl;
161	  }
162	  makeToolCard(name) {
163	    const card = el("details", "tool");     // collapsed by default; click to expand
164	    const head = el("summary", "tool-head");
165	    head.appendChild(el("span", "tname", esc(name || "tool")));
166	    const summary = el("span", "tsummary", "");
167	    head.appendChild(summary);
168	    const st = el("span", "tstate", "running…");
169	    head.appendChild(st);
170	    card.appendChild(head);
171	    const pre = el("pre");
172	    card.appendChild(pre);
173	    this.current.body.appendChild(card);
174	    return { type: "tool", el: card, pre, state: st, summary, name };
175	  }
176	  finalizeToolInputs(message) {
177	    (message.content || []).forEach((c) => {
178	      if (c.type !== "tool_use") return;
179	      for (const idx in this.blocks) {
180	        const b = this.blocks[idx];
181	        if (b.type === "tool" && b.name === c.name && b.pre && !b.done) {
182	          try { b.pre.textContent = JSON.stringify(c.input, null, 2); } catch (_) {}
183	          if (b.summary) b.summary.textContent = toolSummary(c.name, c.input);
184	          b.id = c.id;
185	        }
186	      }
187	    });
188	  }
189	  applyToolResults(message) {
190	    (message.content || []).forEach((c) => {
191	      if (c.type !== "tool_result") return;
192	      for (const idx in this.blocks) {
193	        const b = this.blocks[idx];
194	        if (b.type === "tool" && b.id === c.tool_use_id && !b.done) {
195	          b.done = true;
196	          b.state.textContent = c.is_error ? "error" : "done";
197	          if (c.is_error) b.state.style.color = "var(--err)";
198	          let txt = c.content;
199	          if (Array.isArray(txt)) txt = txt.map((p) => p.text || "").join("");
200	          b.el.appendChild(el("pre", "tool-result", esc(String(txt || "").slice(0, 6000))));
201	        }
202	      }
203	    });
204	  }
205	  handleStreamEvent(ev) {
206	    const e = ev.event;
207	    if (!e) return;
208	    const wasBottom = this.atBottom();
209	    if (e.type === "message_start") {
210	      if (!this.current) this.beginAssistant();
211	    } else if (e.type === "content_block_start") {
212	      const idx = e.index, cb = e.content_block || {};
213	      if (cb.type === "thinking") {
214	        const d = el("details", "think");
215	        d.appendChild(el("summary", null, "thinking"));
216	        const tb = el("div", "think-body");
217	        d.appendChild(tb);
218	        this.current.body.appendChild(d);
219	        this.blocks[idx] = { type: "thinking", el: tb };
220	      } else if (cb.type === "text") {
221	        this.blocks[idx] = { type: "text", el: this.ensureTextEl() };
222	      } else if (cb.type === "tool_use") {
223	        this.blocks[idx] = this.makeToolCard(cb.name);
224	        this.toolInputs[idx] = "";
225	      }
226	    } else if (e.type === "content_block_delta") {
227	      const b = this.blocks[e.index], d = e.delta || {};
228	      if (!b) return;
229	      if (d.type === "thinking_delta") b.el.textContent += d.thinking || "";
230	      else if (d.type === "text_delta") {
231	        this.current.text += d.text || "";
232	        this.current.textEl.innerHTML = md(this.current.text) + '<span class="cursor">&nbsp;</span>';
233	      } else if (d.type === "input_json_delta") {
234	        this.toolInputs[e.index] += d.partial_json || "";
235	        b.pre.textContent = this.toolInputs[e.index];
236	      }
237	    } else if (e.type === "content_block_stop") {
238	      const b = this.blocks[e.index];
239	      if (b && b.type === "text" && this.current.textEl) this.current.textEl.innerHTML = md(this.current.text);
240	    }
241	    if (wasBottom) this.scroll();
242	  }
243	
244	  /* render a complete (imported) MIST message from normalized blocks */
245	  renderHistMsg(blocks) {
246	    const body = this.addMsg("mist", "MIST");
247	    blocks.forEach((b) => {
248	      if (b.kind === "text") {
249	        body.appendChild(el("div", "md", md(b.text)));
250	      } else if (b.kind === "thinking") {
251	        const d = el("details", "think");
252	        d.appendChild(el("summary", null, "thinking"));
253	        const tb = el("div", "think-body");
254	        tb.textContent = b.text;
255	        d.appendChild(tb);
256	        body.appendChild(d);
257	      } else if (b.kind === "tool") {
258	        const card = el("details", "tool");
259	        const head = el("summary", "tool-head");
260	        head.appendChild(el("span", "tname", esc(b.name || "tool")));
261	        head.appendChild(el("span", "tsummary", esc(toolSummary(b.name, b.input))));
262	        head.appendChild(el("span", "tstate", b.result ? "done" : ""));
263	        card.appendChild(head);
264	        const pre = el("pre");
265	        try { pre.textContent = JSON.stringify(b.input, null, 2); }
266	        catch (_) { pre.textContent = String(b.input); }
267	        card.appendChild(pre);
268	        if (b.result) card.appendChild(el("pre", "tool-result", esc(String(b.result).slice(0, 6000))));
269	        body.appendChild(card);
270	      }
271	    });
272	    this.scroll();
273	  }
274	
275	  onEvent(o) {
276	    switch (o.type) {
277	      case "user_text":
278	        this.addMsg("user", "Alex").textContent = o.text;
279	        break;
280	      case "mist_msg":
281	        this.renderHistMsg(o.blocks || []);
282	        break;
283	      case "system":
284	        if (o.subtype === "init") {
285	          this.init = o;
286	          lastInit = {
287	            model: o.model, permissionMode: o.permissionMode, tools: o.tools,
288	            mcp_servers: o.mcp_servers, skills: o.skills, slash_commands: o.slash_commands,
289	          };
290	          try { localStorage.setItem("lastInit", JSON.stringify(lastInit)); } catch (_) {}
291	          if (this.active) fillCaps(o);
292	          if (!this.current) this.setStatus("idle", "idle");
293	        }
294	        else if (o.subtype === "status" && o.status === "requesting") this.setStatus("thinking", "thinking");
295	        break;
296	      case "stream_event":
297	        if (o.event && o.event.type === "message_start") this.setStatus("working", "responding");
298	        this.handleStreamEvent(o);
299	        break;
300	      case "assistant":
301	        if (!this.current) this.beginAssistant();
302	        this.finalizeToolInputs(o.message || {});
303	        break;
304	      case "user":
305	        this.applyToolResults(o.message || {});
306	        break;
307	      case "context":
308	        this.ctxPct = o.pct;
309	        if (this.active) setCtxBadge(o.pct);
310	        break;
311	      case "result":
312	        this.current = null;
313	        this.setStatus("idle", "idle");
314	        this.lastUsage = usageText(o);
315	        if (this.active) $("#usage").textContent = this.lastUsage;
316	        break;
317	      case "stderr":
318	        if (/error|fatal|exception/i.test(o.text)) this.notice("stderr: " + o.text, true);
319	        break;
320	      case "process_exit":
321	        this.setStatus("error", "exited");
322	        this.notice("Claude process exited (code " + o.code + ").", true);
323	        break;
324	    }
325	  }
326	
327	  async send(text) {
328	    // The user bubble is rendered from the broadcast user_text event (so it
329	    // also appears on replay); don't add it optimistically here.
330	    this.setStatus("thinking", "thinking");
331	    this.lastActivity = Date.now();
332	    renderTabs();
333	    try {
334	      const r = await fetch("/send/" + this.id, {
335	        method: "POST", headers: { "Content-Type": "application/json" },
336	        body: JSON.stringify({ text }),
337	      });
338	      const j = await r.json();
339	      if (!j.ok) this.notice("Could not deliver message to Claude.", true);
340	      if (j.title && this.title === "New chat") { this.title = j.title; renderTabs(); }
341	    } catch (err) {
342	      this.notice("Send failed: " + err, true);
343	    }
344	  }
345	
346	  destroy() {
347	    if (this.es) this.es.close();
348	    this.logEl.remove();
349	  }
350	}
351	
352	/* ---------- top-bar reflectors (active session) ---------- */
353	function applyStatus(s) {
354	  statusEl.dataset.state = s.statusState;
355	  statusEl.textContent = s.statusLabel;
356	}
357	/* cycle MIST's spinner verbs in any working session's chat spinner (slow) */
358	setInterval(() => {
359	  if (!SPINNER_VERBS.length) return;
360	  spinnerIdx = (spinnerIdx + 1) % SPINNER_VERBS.length;
361	  const verb = SPINNER_VERBS[spinnerIdx] + "…";
362	  sessions.forEach((s) => {
363	    if (s.spinnerEl) {
364	      const sv = s.spinnerEl.querySelector(".sv");
365	      if (sv) sv.textContent = verb;
366	    }
367	  });
368	}, 5000);
369	
370	/* ---------- model switcher card ---------- */
371	function renderModelCard() {
372	  const list = $("#modelList");
373	  list.innerHTML = "";
374	  const cur = (activeId && sessions.get(activeId) && sessions.get(activeId).model) || "";
375	  MODELS.forEach((m) => {
376	    const row = el("div", "modelrow" + (m.id === cur ? " sel" : ""), esc(m.label));
377	    row.addEventListener("click", () => selectModel(m));
378	    list.appendChild(row);
379	  });
380	}
381	async function selectModel(m) {
382	  $("#modelCard").hidden = true;
383	  if (!activeId) return;
384	  const s = sessions.get(activeId);
385	  s.model = m.id;
386	  $("#model").textContent = m.id ? m.id : "model: default";
387	  s.notice("Model set to " + m.label + ". Applies to your next message.");
388	  try {
389	    await fetch("/sessions/" + activeId + "/model", {
390	      method: "POST", headers: { "Content-Type": "application/json" },
391	      body: JSON.stringify({ model: m.id }),
392	    });
393	  } catch (_) {}
394	}
395	function setCtxBadge(pct) {
396	  $("#ctx").textContent = pct == null ? "ctx —" : "ctx " + pct + "%";
397	}
398	function setCount(id, arr) {
399	  const e = $(id);
400	  if (e) e.textContent = "(" + ((arr && arr.length) || 0) + ")";
401	}
402	function fillSettings(c) {
403	  chips("#capMcp", c.mcp_servers);
404	  chips("#capTools", c.tools);
405	  chips("#capSkills", c.skills);
406	  chips("#capSlash", c.slash_commands);
407	  setCount("#nMcp", c.mcp_servers);
408	  setCount("#nTools", c.tools);
409	  setCount("#nSkills", c.skills);
410	  setCount("#nSlash", c.slash_commands);
411	}
412	function fillCaps(init) {
413	  $("#model").textContent = init.model || "model —";
414	  $("#perm").textContent = "perm: " + (init.permissionMode || "—");
415	  fillSettings(init);
416	}
417	function chips(id, items) {
418	  const c = $(id);
419	  c.innerHTML = "";
420	  (items || []).forEach((it) => {
421	    const name = typeof it === "string" ? it : it.name;
422	    const span = el("span", null, esc(name));
423	    if (typeof it === "object" && it.status && it.status !== "connected") span.classList.add("pending");
424	    c.appendChild(span);
425	  });
426	}
427	function usageText(r) {
428	  const u = r.usage || {};
429	  const cost = r.total_cost_usd != null ? "$" + r.total_cost_usd.toFixed(4) : "";
430	  const tok = u.output_tokens != null ? u.output_tokens + " out" : "";
431	  const ms = r.duration_ms ? (r.duration_ms / 1000).toFixed(1) + "s" : "";
432	  return [tok, ms, cost].filter(Boolean).join("  ·  ");
433	}
434	
435	/* ---------- tab rail ---------- */
436	function sortedSessions() {
437	  return [...sessions.values()].sort((a, b) => {
438	    if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;   // pinned first
439	    return b.lastActivity - a.lastActivity;                // then newest first
440	  });
441	}
442	function renderTabs() {
443	  tabsEl.innerHTML = "";
444	  const list = sortedSessions();
445	  const anyPinned = list.some((s) => s.pinned);
446	  let section = null;   // which header we've emitted so far: "pinned" | "recent"
447	  list.forEach((s) => {
448	    if (anyPinned) {
449	      const want = s.pinned ? "pinned" : "recent";
450	      if (want !== section) {
451	        const h = el("div", "tabsection" + (s.pinned ? " pinned" : ""),
452	          s.pinned ? "◆ pinned" : "recent");
453	        tabsEl.appendChild(h);
454	        section = want;
455	      }
456	    }
457	    const t = el("div", "tab" + (s.id === activeId ? " active" : "") + (s.pinned ? " pinned" : ""));
458	    t.appendChild(el("span", "dot " + s.statusState));
459	    t.appendChild(el("span", "ttitle", esc(s.title)));
460	    const pin = el("span", "tpin" + (s.pinned ? " on" : ""), s.pinned ? "◆" : "◇");
461	    pin.title = s.pinned ? "Unpin" : "Pin";
462	    pin.addEventListener("click", (ev) => { ev.stopPropagation(); togglePin(s.id); });
463	    t.appendChild(pin);
464	    const x = el("span", "tclose", "×");
465	    x.title = "Close";
466	    x.addEventListener("click", (ev) => { ev.stopPropagation(); closeSession(s.id); });
467	    t.appendChild(x);
468	    t.addEventListener("click", () => switchTo(s.id));
469	    tabsEl.appendChild(t);
470	  });
471	}
472	async function togglePin(id) {
473	  const s = sessions.get(id);
474	  if (!s) return;
475	  s.pinned = !s.pinned;
476	  renderTabs();
477	  try { await fetch("/sessions/" + id + "/pin", { method: "POST" }); } catch (_) {}
478	}
479	function switchTo(id) {
480	  const s = sessions.get(id);
481	  if (!s) return;
482	  activeId = id;
483	  sessions.forEach((x) => { x.logEl.hidden = x.id !== id; });
484	  // reflect this session into the top bar
485	  if (s.init) fillCaps(s.init); else { $("#model").textContent = "model —"; $("#perm").textContent = "perm —"; }
486	  applyStatus(s);
487	  setCtxBadge(s.ctxPct);
488	  $("#usage").textContent = s.lastUsage || "";
489	  renderTabs();
490	  s.scroll();
491	  input.focus();
492	}
493	async function createSession() {
494	  const r = await fetch("/sessions", { method: "POST" });
495	  const j = await r.json();
496	  const s = new Session(j.id, j.title);
497	  sessions.set(j.id, s);
498	  switchTo(j.id);
499	  return s;
500	}
501	async function closeSession(id) {
502	  const s = sessions.get(id);
503	  if (!s) return;
504	  await fetch("/sessions/" + id, { method: "DELETE" }).catch(() => {});
505	  s.destroy();
506	  sessions.delete(id);
507	  if (activeId === id) {
508	    const next = sortedSessions()[0];
509	    if (next) switchTo(next.id);
510	    else { activeId = null; createSession(); }
511	  } else {
512	    renderTabs();
513	  }
514	}
515	
516	/* periodically refresh tab status dots */
517	setInterval(renderTabs, 1500);
518	
519	/* ---------- usage badges (5h / 7d) ---------- */
520	function fmtReset(ts) {
521	  if (!ts) return "";
522	  const diff = ts - Math.floor(Date.now() / 1000);
523	  if (diff <= 0) return "now";
524	  if (diff < 3600) return "<1h";
525	  if (diff < 86400) return Math.floor(diff / 3600) + "h";
526	  return Math.ceil(diff / 86400) + "d";
527	}
528	async function pollUsage() {
529	  try {
530	    const u = await (await fetch("/usage")).json();
531	    const r5 = $("#r5h"), r7 = $("#r7d");
532	    if (!u.available) { r5.textContent = "5h —"; r7.textContent = "7d —"; return; }
533	    const f = u.five_hour || {}, w = u.seven_day || {};
534	    r5.textContent = f.used_percentage != null
535	      ? `5h ${Math.round(f.used_percentage)}% · ${fmtReset(f.resets_at)}` : "5h —";
536	    r7.textContent = w.used_percentage != null
537	      ? `7d ${Math.round(w.used_percentage)}% · resets ${fmtReset(w.resets_at)}` : "7d —";
538	    const stale = u.age_seconds > 1800 ? ` (cache ${Math.round(u.age_seconds / 60)}m old)` : "";
539	    r5.title = "5-hour limit used" + stale;
540	    r7.title = "7-day limit used" + stale;
541	  } catch (_) {}
542	}
543	setInterval(pollUsage, 45000);
544	pollUsage();
545	
546	/* ---------- boot greeting ---------- */
547	function bootGreeting() {
548	  fetch("/greeting").then((r) => r.json()).then((g) => {
549	    if (g && g.text && activeId) {
550	      const s = sessions.get(activeId);
551	      const body = s.addMsg("mist", "MIST");
552	      body.innerHTML = '<em class="greet">' + esc(g.text) + "</em>";
553	    }
554	  }).catch(() => {});
555	}
556	
557	/* ---------- composer + file picker ---------- */
558	function insertPaths(paths) {
559	  if (!paths || !paths.length) return;
560	  const q = paths.map((p) => (/\s/.test(p) ? '"' + p + '"' : p)).join(" ");
561	  const cur = input.value;
562	  input.value = cur + (cur && !cur.endsWith(" ") ? " " : "") + q + " ";
563	  input.dispatchEvent(new Event("input"));
564	  input.focus();
565	}
566	function sendActive() {
567	  const text = input.value.trim();
568	  if (!text || !activeId) return;
569	  input.value = ""; input.style.height = "auto";
570	  sessions.get(activeId).send(text);
571	}
572	input.addEventListener("input", () => {
573	  input.style.height = "auto";
574	  input.style.height = Math.min(input.scrollHeight, 200) + "px";
575	  updateSlash();
576	});
577	input.addEventListener("keydown", (e) => {
578	  if (slashOpen && slashItems.length) {
579	    if (e.key === "ArrowDown") { e.preventDefault(); slashIdx = (slashIdx + 1) % slashItems.length; paintSlashSel(); return; }
580	    if (e.key === "ArrowUp")   { e.preventDefault(); slashIdx = (slashIdx - 1 + slashItems.length) % slashItems.length; paintSlashSel(); return; }
581	    if (e.key === "Enter" || e.key === "Tab") { e.preventDefault(); acceptSlash(slashIdx); return; }
582	    if (e.key === "Escape")    { e.preventDefault(); hideSlash(); return; }
583	  }
584	  if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendActive(); }
585	});
586	input.addEventListener("blur", () => setTimeout(hideSlash, 120));
587	
588	/* ---------- inline slash-command autocomplete ---------- */
589	const slashMenu = $("#slashMenu");
590	let slashItems = [];   // currently filtered command names
591	let slashIdx = 0;
592	let slashOpen = false;
593	function slashAll() {
594	  const raw = (lastInit && lastInit.slash_commands) || [];
595	  return raw.map((it) => (typeof it === "string" ? it : it.name)).filter(Boolean);
596	}
597	function updateSlash() {
598	  // Only trigger on a leading slash with no space yet: "/", "/de", "/news-b"…
599	  const m = /^\/([a-zA-Z0-9:_-]*)$/.exec(input.value);
600	  if (!m) return hideSlash();
601	  const q = m[1].toLowerCase();
602	  slashItems = slashAll()
603	    .filter((c) => c.toLowerCase().includes(q))
604	    .sort((a, b) => {
605	      const as = a.toLowerCase().startsWith(q), bs = b.toLowerCase().startsWith(q);
606	      if (as !== bs) return as ? -1 : 1;          // prefix matches first
607	      return a.localeCompare(b);
608	    })
609	    .slice(0, 8);
610	  if (!slashItems.length) return hideSlash();
611	  slashIdx = 0;
612	  renderSlash();
613	}
614	function renderSlash() {
615	  slashMenu.innerHTML = "";
616	  slashMenu.appendChild(el("div", "slash-head", "slash commands · ↑↓ to choose, ⏎ to insert"));
617	  slashItems.forEach((c, i) => {
618	    const row = el("div", "slash-item" + (i === slashIdx ? " sel" : ""));
619	    row.appendChild(el("span", "slash-name", "/" + esc(c)));
620	    row.addEventListener("mousedown", (e) => { e.preventDefault(); acceptSlash(i); });
621	    row.addEventListener("mouseenter", () => { slashIdx = i; paintSlashSel(); });
622	    slashMenu.appendChild(row);
623	  });
624	  slashMenu.hidden = false;
625	  slashOpen = true;
626	}
627	function paintSlashSel() {
628	  [...slashMenu.querySelectorAll(".slash-item")].forEach((c, i) => c.classList.toggle("sel", i === slashIdx));
629	}
630	function hideSlash() { slashMenu.hidden = true; slashOpen = false; slashItems = []; }
631	function acceptSlash(i) {
632	  const c = slashItems[i];
633	  if (!c) return;
634	  input.value = "/" + c + " ";
635	  hideSlash();
636	  input.focus();
637	  input.style.height = "auto";
638	  input.style.height = Math.min(input.scrollHeight, 200) + "px";
639	}
640	$("#sendBtn").addEventListener("click", sendActive);
641	$("#newTab").addEventListener("click", createSession);
642	$("#settingsBtn").addEventListener("click", () => {
643	  if (lastInit) fillSettings(lastInit);   // last-known MCP servers + tools
644	  $("#capPanel").hidden = false;
645	});
646	
647	/* ---------- quick access (double-tap Option) ---------- */
648	async function loadQuickAccess() {
649	  try {
650	    const cfg = await (await fetch("/quick-access")).json();
651	    $("#qaEnabled").checked = !!cfg.enabled;
652	  } catch (_) {}
653	  refreshQaPerm();
654	}
655	async function refreshQaPerm() {
656	  try {
657	    const d = await (await fetch("/quick-access/diag")).json();
658	    $("#qaPermRow").hidden = d.ax_trusted === true;
659	  } catch (_) {}
660	}
661	$("#qaEnabled").addEventListener("change", (e) => {
662	  fetch("/quick-access", {
663	    method: "POST", headers: { "Content-Type": "application/json" },
664	    body: JSON.stringify({ enabled: e.target.checked }),
665	  }).catch(() => {});
666	});
667	$("#qaGrant").addEventListener("click", async () => {
668	  try { await fetch("/quick-access/request-permission", { method: "POST" }); } catch (_) {}
669	  setTimeout(refreshQaPerm, 1500);
670	});
671	loadQuickAccess();
672	$("#capClose").addEventListener("click", () => { $("#capPanel").hidden = true; });
673	$("#modelBtn").addEventListener("click", () => { renderModelCard(); $("#modelCard").hidden = false; });
674	$("#modelClose").addEventListener("click", () => { $("#modelCard").hidden = true; });
675	
676	const hiddenFile = $("#hiddenFile");
677	$("#fileBtn").addEventListener("click", async () => {
678	  try {
679	    if (window.pywebview && window.pywebview.api && window.pywebview.api.pick_file) {
680	      insertPaths(await window.pywebview.api.pick_file());
681	    } else { hiddenFile.click(); }
682	  } catch (e) { if (activeId) sessions.get(activeId).notice("File picker error: " + e, true); }
683	});
684	hiddenFile.addEventListener("change", () => {
685	  insertPaths(Array.from(hiddenFile.files).map((f) => f.name));
686	  hiddenFile.value = "";
687	});
688	
689	/* ---------- resizable tab rail ---------- */
690	(function () {
691	  const handle = $("#railResize");
692	  const root = document.documentElement;
693	  const DEFAULT = 196, MIN = 120, MAX = 560;
694	  const saved = parseInt(localStorage.getItem("railW") || "", 10);
695	  if (saved >= MIN && saved <= MAX) root.style.setProperty("--rail-w", saved + "px");
696	  let dragging = false;
697	  handle.addEventListener("mousedown", (e) => {
698	    dragging = true; handle.classList.add("dragging");
699	    document.body.classList.add("col-resizing"); e.preventDefault();
700	  });
701	  window.addEventListener("mousemove", (e) => {
702	    if (!dragging) return;
703	    root.style.setProperty("--rail-w", Math.max(MIN, Math.min(MAX, e.clientX)) + "px");
704	  });
705	  window.addEventListener("mouseup", () => {
706	    if (!dragging) return;
707	    dragging = false; handle.classList.remove("dragging");
708	    document.body.classList.remove("col-resizing");
709	    const cur = parseInt(getComputedStyle(root).getPropertyValue("--rail-w"), 10);
710	    if (cur) localStorage.setItem("railW", cur);
711	  });
712	  handle.addEventListener("dblclick", () => {
713	    root.style.setProperty("--rail-w", DEFAULT + "px");
714	    localStorage.setItem("railW", DEFAULT);
715	  });
716	})();
717	
718	/* ---------- quick-entry hand-off ---------- */
719	async function pollPending() {
720	  try {
721	    const j = await (await fetch("/pending-open")).json();
722	    if (!j.id) return;
723	    if (!sessions.has(j.id)) {
724	      const list = await (await fetch("/sessions")).json();
725	      const info = list.find((x) => x.id === j.id) || {};
726	      sessions.set(j.id, new Session(j.id, info.title, info));
727	    }
728	    switchTo(j.id);
729	  } catch (_) {}
730	}
731	window.__syncPending = pollPending;     // called when the main window is surfaced
732	setInterval(pollPending, 1500);
733	
734	/* ---------- copy buttons + external links (event delegation) ---------- */
735	function openExternal(href) {
736	  try {
737	    if (window.pywebview && window.pywebview.api && window.pywebview.api.open_url) {
738	      window.pywebview.api.open_url(href);
739	      return;
740	    }
741	  } catch (_) {}
742	  window.open(href, "_blank", "noopener");
743	}
744	logs.addEventListener("click", async (e) => {
745	  const btn = e.target.closest(".copy-btn");
746	  if (btn) {
747	    const pre = btn.parentElement.querySelector("pre");
748	    const text = pre ? pre.textContent : "";
749	    try {
750	      await navigator.clipboard.writeText(text);
751	    } catch (_) {
752	      const ta = el("textarea");
753	      ta.value = text;
754	      ta.style.position = "fixed";
755	      ta.style.opacity = "0";
756	      document.body.appendChild(ta);
757	      ta.select();
758	      try { document.execCommand("copy"); } catch (_) {}
759	      ta.remove();
760	    }
761	    btn.classList.add("copied");
762	    btn.textContent = "Copied";
763	    clearTimeout(btn._t);
764	    btn._t = setTimeout(() => { btn.classList.remove("copied"); btn.textContent = "Copy"; }, 1400);
765	    return;
766	  }
767	  const link = e.target.closest("a[href]");
768	  if (link) {
769	    const href = link.getAttribute("href");
770	    if (/^https?:/i.test(href)) { e.preventDefault(); openExternal(href); }
771	  }
772	});
773	
774	/* ---------- boot ---------- */
775	async function boot() {
776	  try {
777	    const cfg = await (await fetch("/config")).json();
778	    if (cfg.spinner_verbs && cfg.spinner_verbs.length) SPINNER_VERBS = cfg.spinner_verbs;
779	    MODELS = cfg.models || [];
780	  } catch (_) {}
781	  const existing = await (await fetch("/sessions")).json();
782	  if (existing.length) {
783	    existing.forEach((info) => sessions.set(info.id, new Session(info.id, info.title, info)));
784	    switchTo(sortedSessions()[0].id);
785	  } else {
786	    await createSession();
787	  }
788	  bootGreeting();
789	  input.focus();
790	}
791	boot();
